  get isDesktop(): boolean {
    return this.viewportWidth >= this.DESKTOP_BREAKPOINT;
  }

  /** Messenger 風サイドバーを表示するか: PC かつチャットページ以外 (top/scheduling除く) */
  get showChatRail(): boolean {
    // チャット以外の主要ページ + 設定/履歴/連絡先などすべての非トップページで表示
    if (!this.isDesktop) return false;
    if (this.isTopPage || this.isChatPage || this.isSchedulingPage) return false;
    return true;
  }

  /** recentChatRooms + ユーザーが作成したルーム (重複除外、ユーザー作成が先頭) */
  get mergedRailRooms() {
    const shared = this.chatState.snapshotUserRooms();
    const sharedConverted = shared.map(s => ({
      id: s.id,
      name: s.name,
      initial: s.initial,
      avatarColor: s.avatarColor,
      avatarImage: s.avatarImage,
      unreadCount: s.unreadCount,
      online: s.online,
      type: s.type,
      memberAvatars: s.memberAvatars,
    }));
    const existing = new Set(sharedConverted.map(r => r.id));
    const remain = this.recentChatRooms.filter(r => !existing.has(r.id));
    return [...sharedConverted, ...remain];
  }

  /** ビューポート高さに応じて表示するアバター数 (それ以外は「他N件」に集約) */
  get visibleRecentRooms() {
    const max = this.calcRailMaxItems();
    return this.mergedRailRooms.slice(0, max);
  }

  get hiddenRecentRoomsCount(): number {
    const max = this.calcRailMaxItems();
    return Math.max(0, this.mergedRailRooms.length - max);
  }

  /** 高さに応じて何件表示するか (アバター56px + gap8px = 64px / 1件) */
  private calcRailMaxItems(): number {
    if (typeof window === 'undefined') return 6;
    const reservedTop = 70 + 16;       // header + 余白
    const reservedBottom = 60 + 16;    // 編集ボタン + 余白
    const overflowReserve = 40;        // 「他N件」表示分
    const usable = Math.max(120, window.innerHeight - reservedTop - reservedBottom - overflowReserve);
    return Math.max(1, Math.floor(usable / 64));
  }

  // ====== ミニチャットウィンドウ (Messenger 風 bottom-right popup) ======
  /** 現在開いているミニチャット (複数同時可能、最大 3 件) */
  openMiniChats: Array<{ room: { id: string; name: string; initial: string; avatarColor: string; avatarImage?: string; type?: string; memberAvatars?: Array<{ initial: string; color: string; image?: string }> }; minimized: boolean; input: string }> = [];
  readonly MAX_MINI_CHATS = 3;
  private readonly MINI_CHATS_STORAGE_KEY = 'schecon.miniChats.open.v1';
  /** 現在フォーカスされているミニチャットの roomId (複数開いている時、ツールバー表示切替に使う) */
  miniChatFocusedId: string | null = null;

