  /** ピッカーで選択した相手で新規チャットを作成し、ミニチャットで即時開く */
  createChatFromPicker(): void {
    if (!this.newChatPickerSelected.length) return;
    const chosen = this.pickerContacts.filter(c => this.newChatPickerSelected.includes(c.id));
    const type: 'direct' | 'group' = chosen.length > 1 ? 'group' : 'direct';
    const name = type === 'direct'
      ? chosen[0].name
      : `グループ (${chosen.length}名)`;
    const initial = (chosen[0].initial || name.charAt(0));
    const avatarColor = type === 'group' ? '#26a69a' : chosen[0].color;
    const nowMs = Date.now();
    const roomId = 'room-' + nowMs;

    // 共有サービスへルーム登録 (リアルタイムに他タブ・chat-page 両方へ反映)
    this.chatState.addUserRoom({
      id: roomId,
      name,
      initial,
      avatarColor,
      type,
      lastMessage: 'チャットを開始しました',
      timestamp: '今',
      updatedAt: nowMs,
      unreadCount: 0,
      memberAvatars: type === 'group'
        ? chosen.slice(0, 2).map(c => ({ initial: c.initial, color: c.color }))
        : undefined,
    });

    this.showNewChatPicker = false;
    this.newChatPickerQuery = '';
    this.newChatPickerSelected = [];

    // 作成と同時にミニチャットで開く (新規ルームは mergedRailRooms 経由で参照可能)
    setTimeout(() => this.openMiniChat(roomId), 0);
  }

