import { Routes } from '@angular/router';

export const routes: Routes = [
  {
    path: '',
    redirectTo: 'top',
    pathMatch: 'full',
  },
  {
    path: 'top',
    loadComponent: () =>
      import('./features/top/pages/top-page/top-page.component').then(
        m => m.TopPageComponent
      ),
  },
  {
    path: 'calendar',
    loadComponent: () =>
      import('./features/calendar/pages/calendar-page/calendar-page.component').then(
        m => m.CalendarPageComponent
      ),
  },
  {
    path: 'mail',
    loadComponent: () =>
      import('./features/mail/pages/mail-page/mail-page.component').then(
        m => m.MailPageComponent
      ),
  },
  {
    path: 'chat',
    loadComponent: () =>
      import('./features/chat/pages/chat-page/chat-page.component').then(
        m => m.ChatPageComponent
      ),
  },
  {
    path: 'chat/:roomId',
    loadComponent: () =>
      import('./features/chat/pages/chat-page/chat-page.component').then(
        m => m.ChatPageComponent
      ),
  },
  {
    path: 'community',
    loadComponent: () =>
      import('./features/community/pages/community-page/community-page.component').then(
        m => m.CommunityPageComponent
      ),
  },
  /* fix (2026-04-27): モーダル → ページ遷移化 (PoC: コミュニティ新規作成).
     /community/create と /community/:id/sub/:subType/create を新設し、
     SP のモーダルクリック不能/反応悪い問題を構造的に解消 */
  {
    path: 'community/create',
    loadComponent: () =>
      import('./features/community/pages/community-create-page/community-create-page.component').then(
        m => m.CommunityCreatePageComponent
      ),
  },
  {
    path: 'community/:id',
    loadComponent: () =>
      import('./features/community/pages/community-page/community-page.component').then(
        m => m.CommunityPageComponent
      ),
  },
  {
    path: 'community/:id/sub/:subType/create',
    loadComponent: () =>
      import('./features/community/pages/community-sub-create-page/community-sub-create-page.component').then(
        m => m.CommunitySubCreatePageComponent
      ),
  },
  {
    path: 'settings/profile',
    loadComponent: () =>
      import('./features/settings/pages/profile-page/profile-page.component').then(
        m => m.ProfilePageComponent
      ),
  },
  {
    path: 'settings/settings',
    loadComponent: () =>
      import('./features/settings/pages/settings-page/settings-page.component').then(
        m => m.SettingsPageComponent
      ),
  },
  {
    path: 'settings/service',
    loadComponent: () =>
      import('./features/settings/pages/service-page/service-page.component').then(
        m => m.ServicePageComponent
      ),
  },
  {
    path: 'address-book',
    loadComponent: () =>
      import('./features/address-book/pages/address-book-page/address-book-page.component').then(
        m => m.AddressBookPageComponent
      ),
  },
  {
    path: 'address-book/:id',
    loadComponent: () =>
      import('./features/address-book/pages/contact-detail-page/contact-detail-page.component').then(
        m => m.ContactDetailPageComponent
      ),
  },
  {
    path: 'history',
    loadComponent: () =>
      import('./features/scheduling/pages/history-page/history-page.component').then(
        m => m.HistoryPageComponent
      ),
  },
  {
    path: 'one-on-one/event/:id',
    loadComponent: () =>
      import('./features/scheduling/pages/one-on-one-event-page/one-on-one-event-page.component').then(
        m => m.OneOnOneEventPageComponent
      ),
  },
  {
    path: 'multiple/event/:id',
    loadComponent: () =>
      import('./features/scheduling/pages/multiple-event-page/multiple-event-page.component').then(
        m => m.MultipleEventPageComponent
      ),
  },
  {
    path: 'confirm',
    loadComponent: () =>
      import('./features/scheduling/pages/confirm-page/confirm-page.component').then(
        m => m.ConfirmPageComponent
      ),
  },
  {
    path: 'event/:id',
    loadComponent: () =>
      import('./features/scheduling/pages/event-redirect-page/event-redirect-page.component').then(
        m => m.EventRedirectPageComponent
      ),
  },
  {
    path: 'multiple/create',
    loadComponent: () =>
      import('./features/scheduling/pages/multiple-create-page/multiple-create-page.component').then(
        m => m.MultipleCreatePageComponent
      ),
  },
  {
    path: 'group/create',
    loadComponent: () =>
      import('./features/scheduling/pages/group-create-page/group-create-page.component').then(
        m => m.GroupCreatePageComponent
      ),
  },
  {
    path: 'one-on-one-create',
    loadComponent: () =>
      import('./features/scheduling/pages/one-on-one-create-page/one-on-one-create-page.component').then(
        m => m.OneOnOneCreatePageComponent
      ),
  },
  {
    path: 'one-on-one/edit/:id',
    loadComponent: () =>
      import('./features/scheduling/pages/one-on-one-edit-page/one-on-one-edit-page.component').then(
        m => m.OneOnOneEditPageComponent
      ),
  },
];
