/**
 * ScrollUiService — 共通スクロール連動 UI 制御
 *
 * 仕様 (全モバイルページ共通):
 *   - 初期状態: show (ヘッダー/グロナビ/composer すべて表示)
 *   - 下スクロール (delta > threshold かつ y > 30): hide
 *   - 上スクロール (delta < 0 もしくは touchend 後 y <= 10): 即 show
 *   - near-bottom (scrollHeight - clientHeight - scrollTop <= 60): show
 *   - input/textarea focus: show
 *
 * 設計:
 *   - window (body ルートスクローラ) を唯一の監視対象にする
 *   - requestAnimationFrame で 1 フレーム 1 回に間引き
 *   - threshold=6px の下向きヒステリシスで手ブレを吸収
 *   - show/hide 時に document.body に `scroll-ui-hidden` クラスをトグルするだけ
 *     (具体の出し引きは CSS で統一)
 *   - focus-in / suspend などのユースケースは show() / suspend() で API 提供
 *
 * PC (window.innerWidth > 1023) ではクラスを触らない (副作用ゼロ)。
 */
import { Injectable, OnDestroy, NgZone } from '@angular/core';

@Injectable({ providedIn: 'root' })
export class ScrollUiService implements OnDestroy {
  private lastY = 0;
  private rafId: number | null = null;
  private hidden = false;
  private suspendUntil = 0;           // この時刻までは hide 判定しない
  private scrollListener: (() => void) | null = null;
  private touchEndListener: (() => void) | null = null;
  private focusInListener: ((e: FocusEvent) => void) | null = null;
  private focusOutListener: ((e: FocusEvent) => void) | null = null;

  // ユーザー調整パラメータ
  private readonly HIDE_DELTA = 6;     // 下向きスクロール検知閾値
  private readonly TOP_Y = 10;         // このスクロール位置以下は常に show
  private readonly NEAR_BOTTOM = 60;   // 底からこの距離以内は show

  constructor(private zone: NgZone) {}

  /**
   * モバイルページで start を呼ぶと、body の scroll-ui-hidden クラスを動的に管理する。
   * PC 幅では何もしない。何度呼んでも idempotent。
   */
  start(): void {
    if (typeof window === 'undefined') return;
    if (this.scrollListener) return; // 既に start 済み
    if (window.innerWidth > 1023) return; // PC ではスクロール連動しない

    this.lastY = window.scrollY || 0;

    const run = () => {
      if (this.rafId) return;
      this.rafId = requestAnimationFrame(() => {
        this.rafId = null;
        if (Date.now() < this.suspendUntil) {
          this.lastY = window.scrollY || 0;
          return;
        }
        const y = window.scrollY || 0;
        const delta = y - this.lastY;
        const doc = document.documentElement;
        const nearBottom = (doc.scrollHeight - doc.clientHeight - y) <= this.NEAR_BOTTOM;

        if (y <= this.TOP_Y || nearBottom) {
          this.applyShow();
        } else if (delta < 0) {
          this.applyShow();                 // 上スクロール (しきい値ゼロで即反応)
        } else if (delta > this.HIDE_DELTA && y > 30) {
          this.applyHide();
        }
        this.lastY = y;
      });
    };

    const onTouchEnd = () => {
      // iOS 慣性スクロール終了時に near-bottom なら show 保証
      requestAnimationFrame(() => {
        const y = window.scrollY || 0;
        const doc = document.documentElement;
        const nearBottom = (doc.scrollHeight - doc.clientHeight - y) <= this.NEAR_BOTTOM;
        if (y <= this.TOP_Y || nearBottom) this.applyShow();
      });
    };

    const onFocusIn = (e: FocusEvent) => {
      const t = e.target as HTMLElement | null;
      if (!t) return;
      if (
        t.tagName === 'INPUT' ||
        t.tagName === 'TEXTAREA' ||
        t.isContentEditable
      ) {
        this.applyShow();
        // キーボード表示の再レイアウト後に保険で一度 show
        setTimeout(() => this.applyShow(), 120);
      }
    };

    // Angular 外で listener を登録 (CD 回避)
    this.zone.runOutsideAngular(() => {
      window.addEventListener('scroll', run, { passive: true });
      window.addEventListener('touchend', onTouchEnd, { passive: true });
      document.addEventListener('focusin', onFocusIn, true);
    });

    this.scrollListener = run;
    this.touchEndListener = onTouchEnd;
    this.focusInListener = onFocusIn;
  }

  /** ページ遷移などで監視を止める (オプショナル)。body クラスは強制的に clear。 */
  stop(): void {
    if (typeof window === 'undefined') return;
    if (this.scrollListener) window.removeEventListener('scroll', this.scrollListener);
    if (this.touchEndListener) window.removeEventListener('touchend', this.touchEndListener);
    if (this.focusInListener) document.removeEventListener('focusin', this.focusInListener, true);
    this.scrollListener = null;
    this.touchEndListener = null;
    this.focusInListener = null;
    if (this.rafId) { cancelAnimationFrame(this.rafId); this.rafId = null; }
    this.forceShow();
  }

  /**
   * ルーム切替やモーダル表示直後など、プログラム的スクロールを走らせる局面で
   * 一時的に hide 判定を無効化 (デフォルト 500ms)。
   */
  suspend(ms = 500): void {
    this.suspendUntil = Date.now() + ms;
  }

  /** UI を強制表示 (focus/near-bottom など) */
  forceShow(): void {
    this.applyShow();
  }

  private applyShow(): void {
    if (!this.hidden) return;
    this.hidden = false;
    document.body.classList.remove('scroll-ui-hidden');
  }

  private applyHide(): void {
    if (this.hidden) return;
    this.hidden = true;
    document.body.classList.add('scroll-ui-hidden');
  }

  ngOnDestroy(): void {
    this.stop();
  }
}
